using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;

namespace ProcSense.EditorTools
{
    /// <summary>
    /// Read-only audit of everything the Quest 2 optimisation depends on (P3-17): per room the renderers, static flags, shaders and SRP Batcher compatibility, lights and their bake mode, reflection
    /// probes, animators and skinned meshes, particle systems and LOD groups; project-wide the Android texture and model import settings. Writes docs/qa/quest2_render_config_audit.md.
    /// Batch: -executeMethod ProcSense.EditorTools.RenderConfigAudit.Run -batchmode -nographics (changes nothing).
    /// </summary>
    public static class RenderConfigAudit
    {
        public static void Run()
        {
            var sb = new StringBuilder("# Quest 2 render configuration audit (generated)\n\n_Generated by `RenderConfigAudit` (read-only; changes no asset). Counts are from the scene files as saved._\n\n");
            Func<Shader, int, int> srp = null;
            var mi = typeof(ShaderUtil).GetMethod("GetSRPBatcherCompatibilityCode", BindingFlags.NonPublic | BindingFlags.Static);
            if (mi != null) srp = (s, pass) => (int)mi.Invoke(null, new object[] { s, pass });
            sb.AppendLine("## 1. Rooms\n");
            sb.AppendLine("| Scene | Renderers | Static (batching) | Skinned | Distinct materials | Distinct shaders | LODGroups | Lightmapped | Reflection probes | Particle systems | Animators |");
            sb.AppendLine("|---|---|---|---|---|---|---|---|---|---|---|");
            var lightRows = new List<string>(); var animRows = new List<string>(); var incompatible = new SortedDictionary<string, string>();
            foreach (var name in new[] { "PatientBay", "Corridor", "OT" })
            {
                var path = AssetDatabase.FindAssets("t:Scene " + name, new[] { "Assets/Scenes" }).Select(AssetDatabase.GUIDToAssetPath).First(p => Path.GetFileNameWithoutExtension(p) == name);
                EditorSceneManager.OpenScene(path, OpenSceneMode.Single);
                var rs = UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None);
                int stat = rs.Count(r => GameObjectUtility.GetStaticEditorFlags(r.gameObject).HasFlag(StaticEditorFlags.BatchingStatic));
                int skinned = rs.Count(r => r is SkinnedMeshRenderer);
                var mats = rs.SelectMany(r => r.sharedMaterials).Where(m => m != null).Distinct().ToList();
                var shaders = mats.Select(m => m.shader).Where(s => s != null).Distinct().ToList();
                int bad = 0;
                if (srp != null)
                    foreach (var s in shaders) { int code = -1; try { code = srp(s, 0); } catch { } if (code != 0 && code != -1) { bad++; incompatible[s.name] = name; } }
                int lm = rs.Count(r => r.lightmapIndex >= 0 && r.lightmapIndex < 65534);
                int lod = UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsInactive.Include, FindObjectsSortMode.None).Length;
                var probes = UnityEngine.Object.FindObjectsByType<ReflectionProbe>(FindObjectsInactive.Include, FindObjectsSortMode.None);
                int ps = UnityEngine.Object.FindObjectsByType<ParticleSystem>(FindObjectsInactive.Include, FindObjectsSortMode.None).Length;
                var anims = UnityEngine.Object.FindObjectsByType<Animator>(FindObjectsInactive.Include, FindObjectsSortMode.None);
                sb.AppendLine($"| {name} | {rs.Length} | {stat} | {skinned} | {mats.Count} | {shaders.Count} | {lod} | {lm} | {probes.Length} ({string.Join("/", probes.Select(p => p.resolution))}) | {ps} | {anims.Length} |");
                foreach (var g in UnityEngine.Object.FindObjectsByType<Light>(FindObjectsInactive.Include, FindObjectsSortMode.None).GroupBy(l => (l.type, l.lightmapBakeType, l.shadows)))
                    lightRows.Add($"| {name} | {g.Key.type} | {g.Key.lightmapBakeType} | {g.Key.shadows} | {g.Count()} | {g.Count(l => l.enabled)} |");
                foreach (var g in anims.GroupBy(a => (a.cullingMode, a.updateMode, a.applyRootMotion, a.GetComponentInChildren<SkinnedMeshRenderer>(true) != null)))
                    animRows.Add($"| {name} | {g.Key.Item1} | {g.Key.Item2} | {g.Key.Item3} | {(g.Key.Item4 ? "has skinned mesh" : "no skinned mesh")} | {g.Count()} |");
                var sk = rs.OfType<SkinnedMeshRenderer>().ToList();
                if (sk.Count > 0)
                    animRows.Add($"| {name} | skinned meshes: {sk.Count}, vertices {sk.Sum(s => s.sharedMesh != null ? s.sharedMesh.vertexCount : 0):N0}, bones {sk.Sum(s => s.bones.Length):N0}, updateWhenOffscreen {sk.Count(s => s.updateWhenOffscreen)}, quality {string.Join("/", sk.Select(s => s.quality).Distinct())}, blendshapes on {sk.Count(s => s.sharedMesh != null && s.sharedMesh.blendShapeCount > 0)} | | | | |");
            }
            sb.AppendLine("\n## 2. Lights\n\n| Scene | Type | Bake mode | Shadows | Count | Enabled |\n|---|---|---|---|---|---|");
            lightRows.ForEach(l => sb.AppendLine(l));
            sb.AppendLine("\n## 3. Animators and skinned meshes\n\n| Scene | Culling mode | Update mode | Root motion | | Count |\n|---|---|---|---|---|---|");
            animRows.ForEach(l => sb.AppendLine(l));
            sb.AppendLine("\n## 4. SRP Batcher\n\nUnity 6 gives no public SRP Batcher compatibility query, so this audit does not guess. The two custom shaders (`ProcSense/Sun Shaft`, `ProcSense/Sun Dust Mote`) declare their properties in `CBUFFER_START(UnityPerMaterial)` and are checked by reading their source; URP Lit, URP Unlit and TextMeshPro SDF Mobile are package shaders that are SRP Batcher compatible.");

            sb.AppendLine("\n## 5. Textures (project-wide, Android import settings)\n");
            int total = 0, readable = 0, noMips = 0, streaming = 0, overridden = 0; long pix = 0; var fmt = new SortedDictionary<string, int>(); var big = new List<(string, int, string)>();
            foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", new[] { "Assets" }))
            {
                var p = AssetDatabase.GUIDToAssetPath(guid); var ti = AssetImporter.GetAtPath(p) as TextureImporter; if (ti == null) continue;
                if (ti.textureType == TextureImporterType.Sprite || ti.textureType == TextureImporterType.GUI || p.Contains("/UI/")) { }
                total++; if (ti.isReadable) readable++; if (!ti.mipmapEnabled) noMips++; if (ti.streamingMipmaps) streaming++;
                var a = ti.GetPlatformTextureSettings("Android"); if (a.overridden) overridden++;
                string f = a.overridden ? a.format.ToString() + " max " + a.maxTextureSize : "default (" + ti.textureCompression + ") max " + ti.maxTextureSize;
                fmt[f] = fmt.TryGetValue(f, out var c) ? c + 1 : 1;
                int size = a.overridden ? a.maxTextureSize : ti.maxTextureSize; if (size >= 2048) big.Add((p, size, f));
            }
            sb.AppendLine($"Textures: {total}; Android override set on {overridden}; Read/Write enabled on {readable} (a CPU copy doubles the memory); no mipmaps {noMips}; streaming mipmaps {streaming}.\n");
            sb.AppendLine("| Android format and size | Textures |\n|---|---|"); foreach (var kv in fmt.OrderByDescending(k => k.Value).Take(18)) sb.AppendLine($"| {kv.Key} | {kv.Value} |");
            sb.AppendLine($"\nTextures at 2048 or larger: {big.Count}" + (big.Count > 0 ? ":\n\n" + string.Join("\n", big.OrderByDescending(b => b.Item2).Take(25).Select(b => $"- `{b.Item1}` {b.Item3}")) : "."));

            sb.AppendLine("\n## 6. Models (project-wide)\n");
            int models = 0, mr = 0; var comp = new SortedDictionary<string, int>(); long verts = 0;
            foreach (var guid in AssetDatabase.FindAssets("t:Model", new[] { "Assets" }))
            {
                var mim = AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid)) as ModelImporter; if (mim == null) continue;
                models++; if (mim.isReadable) mr++; comp[mim.meshCompression.ToString()] = comp.TryGetValue(mim.meshCompression.ToString(), out var c) ? c + 1 : 1;
            }
            sb.AppendLine($"Model files: {models}; Read/Write enabled on {mr}; mesh compression: " + string.Join(", ", comp.Select(k => $"{k.Key} {k.Value}")) + ".");

            sb.AppendLine("\n## 7. Player and pipeline settings (Android)\n");
            sb.AppendLine($"- Scripting backend {PlayerSettings.GetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Android)}, architectures {PlayerSettings.Android.targetArchitectures}, managed stripping {PlayerSettings.GetManagedStrippingLevel(UnityEditor.Build.NamedBuildTarget.Android)}, GPU skinning {PlayerSettings.gpuSkinning}, graphics APIs {string.Join("/", PlayerSettings.GetGraphicsAPIs(BuildTarget.Android))}, mip stripping {PlayerSettings.mipStripping}, static batching {PlayerSettings.GetStaticBatchingForPlatform(BuildTarget.Android)}, dynamic batching {PlayerSettings.GetDynamicBatchingForPlatform(BuildTarget.Android)}, frame timing stats {PlayerSettings.enableFrameTimingStats}.");
            sb.AppendLine($"- Colour space {PlayerSettings.colorSpace}; texture compression default {EditorUserBuildSettings.androidBuildSubtarget}; build type {EditorUserBuildSettings.androidBuildType}.");
            for (int i = 0; i < QualitySettings.names.Length; i++) sb.AppendLine($"- Quality level {i} `{QualitySettings.names[i]}`: pipeline `{(QualitySettings.GetRenderPipelineAssetAt(i) != null ? QualitySettings.GetRenderPipelineAssetAt(i).name : "none")}`");
            File.WriteAllText("../docs/qa/quest2_render_config_audit.md", sb.ToString().Replace("\r\n", "\n"));
            Debug.Log("[RenderConfigAudit] written");
            EditorApplication.Exit(0);
        }
    }
}
